// e2e-only fixture (freeze F9): the client has published no dentist, guide, case or testimonial
// yet, so their templates have no page to screenshot, scan or audit. This adds one of each on top
// of the real seed, every visible string starting «نمونهٔ آزمایشی». `npm run db:e2e` runs it after
// the seeder; src/seed never does. Safe to repeat: it finds its own documents and updates them.
// `payload run` passes no flags, so the database comes from DATABASE_URL like the seeder's.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import config from '@payload-config';
import { getPayload, type Where } from 'payload';
import sharp from 'sharp';

import { readEnv } from '@/lib/env';
import { SEED_CONTEXT } from '@/seed/run';
import { lexicalFrom } from '@/seed/transforms';

const MARK = 'نمونهٔ آزمایشی';
const COUNCIL_NUMBER = '0000000';
const FIXTURE_KEY = 'qa-fixture';
const GUIDE_KEY = 'guide-first-visit';

// It overwrites the guide-first-visit page, so it runs only where tests/setup/e2eUsers.ts runs: a
// database whose name or file name contains "e2e".
function databaseName(url = ''): string {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'file:' ? path.basename(url.slice('file:'.length)) : parsed.pathname;
  } catch {
    return '';
  }
}
const env = readEnv();
if (
  !/e2e/i.test(databaseName(process.env.DATABASE_URL)) ||
  env.nodeEnv === 'production' ||
  env.allowIndexing
) {
  throw new Error(
    'qa-fixture: refused. It writes sample people and overwrites the first-visit guide, so it runs only on an e2e database (DATABASE_URL naming e.g. .data/e2e.db or sefid_e2e) outside production; use npm run db:e2e.',
  );
}

const payload = await getPayload({ config });
const context = SEED_CONTEXT;

async function first<T>(find: Promise<{ docs: T[] }>): Promise<T | undefined> {
  return (await find).docs[0];
}

/** A media document from generated bytes, matched by `seedSource`. */
async function media(source: string, alt: string, file: () => Promise<Buffer>, mimetype: string) {
  const found = await first(
    payload.find({
      collection: 'media',
      where: { seedSource: { equals: source } },
      limit: 1,
      depth: 0,
    }),
  );
  if (found) return found.id;
  const data = await file();
  const doc = await payload.create({
    collection: 'media',
    data: { alt, seedSource: source },
    file: { data, name: path.basename(source), mimetype, size: data.length },
    context,
  });
  return doc.id;
}

/** A neutral grey JPEG of the exact size: a labeled stand-in, never a picture of a person. */
const grey = (width: number, height: number, shade: number) => () =>
  sharp({ create: { width, height, channels: 3, background: { r: shade, g: shade, b: shade } } })
    .jpeg({ quality: 80 })
    .toBuffer();

const video = async () => readFileSync(fileURLToPath(new URL('./qa-video.mp4', import.meta.url)));

/** Create, or bring an earlier fixture document back to this content (and published). */
async function upsert<C extends 'doctors' | 'cases' | 'testimonials'>(
  collection: C,
  where: Where,
  data: Record<string, unknown>,
) {
  const found = await first(payload.find({ collection, where, limit: 1, depth: 0 }));
  const values = { ...data, _status: 'published' } as never;
  const doc = found
    ? await payload.update({ collection, id: found.id, data: values, context })
    : await payload.create({ collection, data: values, context });
  return doc as { id: number; slug?: string };
}

const services = await payload.find({
  collection: 'services',
  where: {
    and: [
      { key: { in: ['ceramic-laminate', 'restoration'] } },
      { _status: { equals: 'published' } },
    ],
  },
  depth: 0,
  pagination: false,
});
const laminate = services.docs.find((s) => s.key === 'ceramic-laminate');
const guidePage = await first(
  payload.find({ collection: 'pages', where: { key: { equals: GUIDE_KEY } }, limit: 1, depth: 0 }),
);
if (!laminate || !guidePage) {
  throw new Error(
    'qa-fixture: the seeded services or the first-visit guide page are missing. Run the seeder first (npm run seed), then this fixture.',
  );
}

const portrait = await media(
  'qa-fixture/dentist.jpg',
  `${MARK}: جای عکس پرترهٔ پزشک`,
  grey(1080, 1350, 196),
  'image/jpeg',
);
const dentist = await upsert(
  'doctors',
  { councilNumber: { equals: COUNCIL_NUMBER } },
  {
    name: MARK,
    specialty: `${MARK}: دندانپزشک عمومی`,
    councilNumber: COUNCIL_NUMBER,
    degrees: [`${MARK}: دکترای عمومی دندانپزشکی`],
    bio: `${MARK}: این معرفی فقط برای آزمودن قالب صفحهٔ پزشک است. پزشکان کلینیک بعد از تأیید مدارک اضافه می‌شوند.`,
    photo: portrait,
    services: services.docs.map((s) => s.id),
    order: 10,
  },
);

const guide = await payload.update({
  collection: 'pages',
  id: guidePage.id,
  data: {
    slug: guidePage.slug,
    title: `${MARK}: اولین مراجعه به کلینیک`,
    lead: `${MARK}: این راهنما فقط برای آزمودن قالب راهنمای بیمار است.`,
    blocks: [
      {
        blockType: 'content',
        body: lexicalFrom(
          `## ${MARK}: پیش از نوبت\n${MARK}: بند اول متن راهنما.\n\n## ${MARK}: روز مراجعه\n- ${MARK}: مورد اول\n- ${MARK}: مورد دوم`,
        ),
      },
      { blockType: 'callout', tone: 'info', text: `${MARK}: نکتهٔ کوتاه راهنما.` },
      {
        blockType: 'faq',
        items: [{ question: `${MARK}: پرسش نمونه؟`, answer: `${MARK}: پاسخ نمونه.` }],
      },
    ],
    reviewer: dentist.id,
    reviewedAt: '2026-10-15T00:00:00.000Z',
    sources: [
      { title: `${MARK}: منبع نمونه`, publisher: 'other', url: 'https://example.org/qa-fixture' },
    ],
    seo: { title: `${MARK}: اولین مراجعه` },
    _status: 'published',
  } as never,
  context,
});

const [before, after] = [
  await media(
    'qa-fixture/case-before.jpg',
    `${MARK}: جای عکس پیش از درمان`,
    grey(1200, 900, 150),
    'image/jpeg',
  ),
  await media(
    'qa-fixture/case-after.jpg',
    `${MARK}: جای عکس پس از درمان`,
    grey(1200, 900, 214),
    'image/jpeg',
  ),
];
const sample = await upsert(
  'cases',
  { sourceFolder: { equals: FIXTURE_KEY } },
  {
    title: `${MARK}: لمینت سرامیکی`,
    sourceFolder: FIXTURE_KEY,
    service: laminate.id,
    doctor: dentist.id,
    before,
    after,
    notes: `${MARK}: توضیح کوتاه نمونهٔ قبل و بعد.`,
    consentConfirmed: true,
    featuredOnHome: true,
    order: 10,
  },
);

const poster = await media(
  'qa-fixture/testimonial-poster.jpg',
  `${MARK}: جای تصویر پیش‌نمایش ویدیو`,
  grey(1280, 720, 170),
  'image/jpeg',
);
const clip = await media('qa-fixture/testimonial.mp4', `${MARK}: ویدیوی نمونه`, video, 'video/mp4');
const voice = await upsert(
  'testimonials',
  { seedKey: { equals: FIXTURE_KEY } },
  {
    patientLabel: MARK,
    service: laminate.id,
    type: 'video',
    video: clip,
    poster,
    transcriptSummary: `${MARK}: خلاصهٔ گفته‌های ویدیوی نمونه.`,
    durationSeconds: 2,
    consentConfirmed: true,
    showOnHome: true,
    order: 10,
    seedKey: FIXTURE_KEY,
  },
);

// The e2e scripts grep this line: `payload run` can exit 0 before the script ran.
payload.logger.info(
  `qa-fixture: dentist /پزشکان/${dentist.slug}, guide ${guide.path}, case ${sample.id}, testimonial ${voice.id}`,
);
